INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Phishing immer per E-Mail durchgeführt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch SMS oder Anrufe möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Kanäle genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Phishing-Angriffs?', 3, '[{"text": "Sensible Daten stehlen", "correct": true, "because": "Zielt auf Passwörter oder Kreditkarten"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Nicht das Ziel"}, {"text": "Software installieren", "correct": false, "because": "Nur sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale weisen auf eine Phishing-Nachricht hin?', 5, '[{"text": "Dringlichkeit", "correct": true, "because": "Fordert schnelles Handeln"}, {"text": "Verdächtige Links", "correct": true, "because": "Führen zu gefälschten Seiten"}, {"text": "Hohe Datenrate", "correct": false, "because": "Kein Phishing-Merkmal"}, {"text": "Persönliche Anrede", "correct": false, "because": "Oft generisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phishing nutzt Social Engineering. b) Es ist immer illegal.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Social Engineering und illegal"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erkennung eines Phishing-Versuchs?', 4, '[{"text": "Absenderadresse", "correct": false, "because": "Kann gefälscht sein"}, {"text": "Rechtschreibfehler", "correct": false, "because": "Hinweis auf Betrug"}, {"text": "Bildschirmfarben", "correct": true, "because": "Irrelevant für Phishing"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zwei-Faktor-Authentifizierung Phishing verhindert?', 2, '[{"text": "Nein", "correct": true, "because": "Reduziert, aber nicht unmöglich"}, {"text": "Ja", "correct": false, "because": "Angriffe weiter möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode schützt am besten vor Phishing?', 3, '[{"text": "Nutzertraining", "correct": true, "because": "Erhöht Wachsamkeit"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Manuelle Updates", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Phishing gibt es?', 5, '[{"text": "Spear-Phishing", "correct": true, "because": "Gezielte Angriffe"}, {"text": "Smishing", "correct": true, "because": "Phishing via SMS"}, {"text": "Cloud-Phishing", "correct": false, "because": "Kein Standardbegriff"}, {"text": "Netzwerk-Phishing", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Phishing-Nachrichten sind oft dringlich. b) Sie sind immer leicht erkennbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft raffiniert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Phishing zu erkennen?', 4, '[{"text": "Linkprüfung", "correct": false, "because": "Enthüllt gefälschte URLs"}, {"text": "Absenderüberprüfung", "correct": false, "because": "Zeigt Spoofing"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Irrelevant für Erkennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Spear-Phishing dasselbe wie normales Phishing?', 2, '[{"text": "Nein", "correct": true, "because": "Gezielter und personalisiert"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Taktiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verhindern Phishing-Angriffe?', 4, '[{"text": "2FA", "correct": true, "because": "Erhöht Kontosicherheit"}, {"text": "E-Mail-Filter", "correct": true, "because": "Blockieren verdächtige Nachrichten"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Phishing immer Malware enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Oft nur Datenklau"}, {"text": "Ja", "correct": false, "because": "Nicht immer Malware"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, um Phishing zu vermeiden?', 3, '[{"text": "Linküberprüfung", "correct": true, "because": "Verhindert Klicks auf Fakes"}, {"text": "Schnelle Antwort", "correct": false, "because": "Erhöht Risiko"}, {"text": "Manuelle Scans", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phishing nutzt gefälschte Webseiten. b) Es ist immer technisch komplex.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist oft simpel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken schützen vor Phishing?', 5, '[{"text": "Schulungen", "correct": true, "because": "Erhöhen Bewusstsein"}, {"text": "Antivirus-Software", "correct": true, "because": "Erkennt Malware"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Schutz"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Phishing-Nachrichten unwichtig?', 3, '[{"text": "Absenderadresse", "correct": false, "because": "Hinweis auf Fälschung"}, {"text": "Dringlichkeit", "correct": false, "because": "Typisches Merkmal"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Phishing-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Phishing auch per SMS erfolgen?', 3, '[{"text": "Ja", "correct": true, "because": "Smishing ist SMS-Phishing"}, {"text": "Nein", "correct": false, "because": "SMS ist ein Kanal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Phishing nur Einzelpersonen betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Firmen sind Ziele"}, {"text": "Ja", "correct": false, "because": "Breites Zielspektrum"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Phishing-Angriff?', 4, '[{"text": "Gefälschte Bank-E-Mail", "correct": true, "because": "Fordert Zugangsdaten"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Aufgabe"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Sicherheitsbezug"}]');
